// Frontend-only boot: do not create the city/player or run the first mission
// until the original menu requests New Game or Load Game.
static int cpuStartupMenu(soft::Renderer& renderer,soft::SoftwareDevice& device,unsigned test){
 gGameState=GS_FRONTEND;FrontEndMenuManager.m_bGameNotLoaded=true;
 FrontEndMenuManager.m_bMenuActive=true;FrontEndMenuManager.m_nCurrScreen=MENUPAGE_START_MENU;
 FrontEndMenuManager.m_nCurrOption=0;FrontEndMenuManager.m_nMenuFadeAlpha=255;
 CMenuManager::m_bStartUpFrontEndRequested=true;TheCamera.Fade(0,FADE_IN);
 cpuHostStage(7,"GTA ORIGINAL START MENU");
 for(unsigned frame=0;;++frame){
  if(cpuHostPaused()){cpuAudioMenuPause(true);while(cpuHostPaused())std::this_thread::sleep_for(std::chrono::milliseconds(10));cpuAudioMenuPause(false);}
  auto begin=std::chrono::steady_clock::now();soft::CoreSettings options(cpuHostSettings());cpuRefreshVehicleLod(options.bits);renderer.renderScale(options.scale());const char* fc=std::getenv("GTA3_FAST_CLUSTER_BOUNDS");device.fastClusterBounds(fc&&!std::strcmp(fc,"1"));device.highQuality(options.smooth());device.bakedLighting(options.bakedLighting());
  if(test){cpuHostTestButtons(0);if(frame==30){
   if(test==2){FrontEndMenuManager.m_nCurrScreen=MENUPAGE_NEW_GAME;FrontEndMenuManager.m_nCurrOption=0;}
   if(test==3){FrontEndMenuManager.m_nCurrScreen=MENUPAGE_LOADING_IN_PROGRESS;FrontEndMenuManager.m_nCurrSaveSlot=0;}
   if(test==4){FrontEndMenuManager.m_nCurrScreen=MENUPAGE_EXIT;FrontEndMenuManager.m_nCurrOption=2;}
  }if((test==2||test==4)&&frame==31)cpuHostTestButtons(16);}
  RsEventHandler(rsFRONTENDIDLE,nil);cpuHostPresent(renderer.pixels());
  if(RsGlobal.quit){puts("PASS FRONTEND QUIT before world initialisation");return 42;}
  if(FrontEndMenuManager.m_bWantToRestart||FrontEndMenuManager.m_bWantToLoad||b_FoundRecentSavedGameWantToLoad){
   bool load=FrontEndMenuManager.m_bWantToLoad||b_FoundRecentSavedGameWantToLoad;
   std::printf("FRONTEND selected %s after %u menu frames\n",load?"LOAD":"NEW GAME",frame);
   FrontEndMenuManager.ShutdownJustMenu();return -1;
  }
  if((test==1||test==5)&&frame==44){if(!FrontEndMenuManager.m_bGameNotLoaded||!FrontEndMenuManager.m_bMenuActive||FrontEndMenuManager.m_nCurrScreen!=MENUPAGE_START_MENU)throw std::runtime_error("startup menu unexpectedly entered world");if(test==5)cpuUiProfile(renderer,true);puts("PASS FRONTEND menu before world initialisation");return 0;}
  if(test&&frame>180)throw std::runtime_error("startup menu test did not select action");
  auto spent=std::chrono::steady_clock::now()-begin;if(spent<std::chrono::milliseconds(33))std::this_thread::sleep_for(std::chrono::milliseconds(33)-spent);
 }
}
